static inline __u8 inet_sk_flowi_flags(const struct sock *sk) /* <=== inet_sk_flowi_flags */ 
{
	__u8 flags = 0;

	if (inet_sk(sk)->transparent || inet_sk(sk)->hdrincl)
		flags |= FLOWI_FLAG_ANYSRC;
	return flags;
}

static inline void sk_tx_queue_clear(struct sock *sk) /* <=== sk_tx_queue_clear */ 
{
	sk->sk_tx_queue_mapping = -1;
}

static inline struct rtable *ip_route_output_ports(struct net *net, struct flowi4 *fl4, /* <=== ip_route_output_ports */ 
						   struct sock *sk,
						   __be32 daddr, __be32 saddr,
						   __be16 dport, __be16 sport,
						   __u8 proto, __u8 tos, int oif)
{
	flowi4_init_output(fl4, oif, sk ? sk->sk_mark : 0, tos,
			   RT_SCOPE_UNIVERSE, proto,
			   sk ? inet_sk_flowi_flags(sk) : 0,
			   daddr, saddr, dport, sport);
	if (sk)
		security_sk_classify_flow(sk, flowi4_to_flowi(fl4));
	return ip_route_output_flow(net, fl4, sk);
}

